
import sqlite3

# Connect to SQLite database
conn = sqlite3.connect("students.db")
cursor = conn.cursor()

# SQL query generated by Gemini
sql_query = """
SELECT COUNT(*)
FROM Students
WHERE status = 'Active';
"""

# Execute SQL query
cursor.execute(sql_query)

# Fetch result
result = cursor.fetchone()

print("SQL Query:", sql_query)
print("Number of Active Students:", result[0])

conn.close()
